import React,{useState}from'react';import{createRoot}from'react-dom/client';import{UIProvider}from'../../src/context/UIContext.jsx';import GuestCheckIn from'../../src/components/GuestCheckIn.jsx';import '../../src/styles/index.css';import '../../src/styles/atelier.css';
