function Demo(){const[guests,setGuests]=useState(initial);const client={post:async(path,body)=>{setGuests(g=>g.map(x=>path.includes(x.id)?{...x,checkedIn:true,checkInCount:body.count}:x));return{data:{}}},delete:async path=>{setGuests(g=>g.map(x=>path.includes(x.id)?{...x,checkedIn:false,checkInCount:null}:x));return{data:{}}}};return <main style={{padding:28,maxWidth:960,margin:'auto'}}><p>Demo lokal — data simulasi, tidak disimpan.</p><h1>Meja penerima tamu</h1><GuestCheckIn invitation={{id:'demo'}} guests={guests} enabled staffClient={client}/></main>}
